mapper.select:
select a.*,b.industry_type as industryType
from client a
left join corp_commerce_info b on a.id = b.client_id
left join normal_base_info c on a.id= c.client_id


        and a.client_status = 'NEW' and a.is_released = 1


        and a.id in (select client_id from corp_commerce_info where group_flag = 1)


        and (
            a.client_type = 'NORMAL'
            or
            a.client_status = 'NEW'
            or
            a.id in (
                select client_id from client_authority
                where deleted = 0 and user_id = #{p.projManagerId}

                    and level in

                        #{item}


            )
            or
            a.id in (select client_id from corp_commerce_info where risk_control_industry_classify = 'INTRA_GROUP_COLLABORATION')
            )

    and a.client_code like CONCAT('%',#{p.clientCode},'%')
    and a.client_name like CONCAT('%',#{p.clientName}, '%')
    and a.client_type = #{p.clientType}
    and b.industry_type=#{p.industryType}
    and b.risk_control_industry_classify=#{p.riskControlIndustryClassify}
    and b.enterprise_nature=#{p.enterpriseNature}

        and a.id in (
            select
                distinct(client_id)
            from
                corp_address_info
            where
                address_type = 'REGISTRY_ADDRESS'
                and province = #{p.provinceCode}
                and city = #{p.cityCode}
                and district = #{p.districtCode}
        )

    and a.create_time >= #{p.createFrom}
    and a.create_time <= #{p.createTo}
    and a.update_time >= #{p.updateFrom}
    and a.update_time < #{p.updateTo}
    and client_status=#{p.clientStatus}
    and process_status=#{p.processStatus}
    and a.create_by = #{p.createById}

        and a.create_by_dept=#{p.createByDeptId}

    and (client_status='TAKE_EFFECT' or (a.client_status='NEW' and a.is_released = 1))

    and a.belong_dept_id=#{p.belongDeptId}

        and (a.belong_dept_id=#{p.belongDeptId} or a.belong_dept_id is null)



        and (a.belong_sponsor_id=#{p.belongSponsorId} or a.create_by=#{p.belongSponsorId})


        and (a.belong_sponsor_id=#{p.belongSponsorId} or a.create_by=#{p.belongSponsorId} or a.belong_sponsor_id
        is null)


        and a.id in

            #{item}



        and (a.client_status = 'TAKE_EFFECT' or (a.client_status = 'NEW' and a.is_released = 1) or client_type = 'NORMAL' or a.id in (select client_id from client_create_record where dept_id in

            #{item}

        ))


        and (a.client_status = 'TAKE_EFFECT' or (a.client_status = 'NEW' and a.is_released = 1) or client_type = 'NORMAL' or a.id in (select client_id from client_create_record where user_id = #{p.queryConditionUserId}))


order by update_time desc

select * from ( SELECT c.id AS clientId, c.client_name AS clientName, c.create_time AS createTime, c.create_by AS createBy, c.client_type AS clientType, c.client_status AS client_status, cc.industry_type AS industryTypeCode, c.province_of_affiliation AS province, cc.risk_control_industry_classify AS riskControlIndustryClassifyCode, cc.enterprise_nature AS enterpriseNatureCode, c.province_of_affiliation AS provinceCode, c.belong_dept_id AS bizDeptId, c.belong_sponsor_id AS projSponsorUserId, alr.classify_result AS assetClassifyResultCode, collection.plan_collection_date as plan_collection_date FROM client c LEFT JOIN corp_commerce_info cc ON c.id = cc.client_id LEFT JOIN ( SELECT a.client_id, a.classify_result FROM asset_classify_client a INNER JOIN ( SELECT acc.client_id, MAX( acc.asset_classify_id ) AS asset_classify_id FROM asset_classify_client acc RIGHT JOIN asset_classify ac ON acc.asset_classify_id = ac.id WHERE ac.finish = 1 GROUP BY acc.client_id ) last ON a.client_id = last.client_id AND a.asset_classify_id = last.asset_classify_id ) alr ON c.id = alr.client_id left join (select MAX(plan_collection_date) as plan_collection_date, client_id as client_id from collection_base_info where cash_flow_item = 'RENT' GROUP BY client_id) collection on collection.client_id = c.id ) temp
and temp.clientName like CONCAT('%',#{p.clientName},'%')
and temp.clientId = #{p.clientId}
and temp.clientId in
#{item}
and temp.riskControlIndustryClassifyCode = #{p.riskControlIndustryClassifyCode}
and temp.assetClassifyResultCode = #{p.assetClassifyResultCode}
and temp.province = #{p.provinceCode}
and temp.bizDeptId = #{p.bizDeptId}
and temp.projSponsorUserId = #{p.projSponsorUserId}
and (temp.bizDeptId in
#{item}
or temp.bizDeptId is null )
and (temp.projSponsorUserId = #{p.authCurrentUserId} )
and temp.createTime >= #{p.createFrom}
and #{p.createTo} >= temp.createTime
and temp.plan_collection_date >= #{p.dealLineFrom}
and #{p.dealLineTo} >= temp.plan_collection_date
and temp.clientId in
#{item}
and temp.client_status in
#{item}

select a.id as clientId, client_name as clientName, usc_code as uscc, b.name as bizDeptName, c.opinion_count as opCount from client a left join bifrost_org b on b.id = a.belong_dept_id left join (select credit_code, count(id) as opinion_count from risk_control_opinion_monitor where risk_type = 1 group by credit_code) c on c.credit_code = a.usc_code where (client_status = 'TAKE_EFFECT' or (client_status = 'NEW' AND is_released = 1)) and client_type = 'CORPORATION' and a.id in
#{item}
and c.opinion_count > 0 and usc_code in (select distinct credit_code from risk_control_warn_monitor where risk_control_warn_monitor.warn_level != 1 )
